-- Fixes catalog_engines.cylinders on 6 engines: a plain inline L4 (ARY) was left NULL,
-- and 5 V-engines were seeded as the wrong layout code -- VR5/VR6 (narrow-angle,
-- single-head VW/Audi "VR" engines) were recorded as the wider V5/V6 layout instead.
--   ARY@132: NULL -> 'L4'
--   AUE@150, AXJ@165, BHE@184: 'V6' -> 'VR6' (VR6 already allowed live)
--   AGZ@110, AQN@125: 'V5' -> 'VR5' (VR5 NOT allowed live -- constraint extended below,
--   every existing value kept, only 'VR5' added)
--
-- Generated by scripts/fill/write-engine-cylinders-fix-migration.mjs, which confirmed
-- live: the current catalog_engines_cylinders_check allows L2, L3, L4, L5, L6, V5, VR6, V6, V8, V10, V12, W12, B4, B6
-- but not VR5, and each of the 6 target rows currently holds its expected "from" value.
--
-- Update that JSON file in the same commit as this migration (CLAUDE.md's 8-CHECK-
-- constraint rule) -- scripts/catalog-vocabularies.json's
-- "catalog_engines.cylinders" entry is updated alongside this file.
--
-- Review-only: NOT run by this session.

BEGIN;

-- Before: show the current state of the 6 target rows and the live constraint.
DO $$
DECLARE r record;
BEGIN
  RAISE NOTICE '--- BEFORE ---';
  FOR r IN
    SELECT code, power_kw, cylinders FROM catalog_engines
    WHERE (code, power_kw) IN (
      ('ARY', 132),
      ('AUE', 150),
      ('AXJ', 165),
      ('BHE', 184),
      ('AGZ', 110),
      ('AQN', 125)
    )
    ORDER BY code, power_kw
  LOOP
    RAISE NOTICE '%@% cylinders = %', r.code, r.power_kw, r.cylinders;
  END LOOP;
END $$;

-- Extend the cylinders CHECK constraint to additionally allow 'VR5' -- every existing
-- value is kept, nothing removed. VR6 is already allowed, so no constraint change is
-- needed for that half of this fix.
ALTER TABLE catalog_engines DROP CONSTRAINT IF EXISTS catalog_engines_cylinders_check;
ALTER TABLE catalog_engines
  ADD CONSTRAINT catalog_engines_cylinders_check
  CHECK (cylinders IS NULL OR cylinders IN (
    'L2', 'L3', 'L4', 'L5', 'L6', 'V5', 'VR6', 'V6', 'V8', 'V10', 'V12', 'W12', 'B4', 'B6', 'VR5'
  ));

-- ARY@132: NULL -> 'L4'
UPDATE catalog_engines
SET cylinders = 'L4'
WHERE code = 'ARY' AND power_kw = 132 AND cylinders IS NULL;
-- AUE@150: 'V6' -> 'VR6'
UPDATE catalog_engines
SET cylinders = 'VR6'
WHERE code = 'AUE' AND power_kw = 150 AND cylinders = 'V6';
-- AXJ@165: 'V6' -> 'VR6'
UPDATE catalog_engines
SET cylinders = 'VR6'
WHERE code = 'AXJ' AND power_kw = 165 AND cylinders = 'V6';
-- BHE@184: 'V6' -> 'VR6'
UPDATE catalog_engines
SET cylinders = 'VR6'
WHERE code = 'BHE' AND power_kw = 184 AND cylinders = 'V6';
-- AGZ@110: 'V5' -> 'VR5'
UPDATE catalog_engines
SET cylinders = 'VR5'
WHERE code = 'AGZ' AND power_kw = 110 AND cylinders = 'V5';
-- AQN@125: 'V5' -> 'VR5'
UPDATE catalog_engines
SET cylinders = 'VR5'
WHERE code = 'AQN' AND power_kw = 125 AND cylinders = 'V5';

-- After: show the new state, and assert exactly 6 rows now hold their target value.
DO $$
DECLARE r record;
DECLARE changed_n integer;
BEGIN
  RAISE NOTICE '--- AFTER ---';
  FOR r IN
    SELECT code, power_kw, cylinders FROM catalog_engines
    WHERE (code, power_kw) IN (
      ('ARY', 132),
      ('AUE', 150),
      ('AXJ', 165),
      ('BHE', 184),
      ('AGZ', 110),
      ('AQN', 125)
    )
    ORDER BY code, power_kw
  LOOP
    RAISE NOTICE '%@% cylinders = %', r.code, r.power_kw, r.cylinders;
  END LOOP;

  SELECT count(*) INTO changed_n FROM catalog_engines WHERE (code, power_kw, cylinders) IN (
    ('ARY', 132, 'L4'),
    ('AUE', 150, 'VR6'),
    ('AXJ', 165, 'VR6'),
    ('BHE', 184, 'VR6'),
    ('AGZ', 110, 'VR5'),
    ('AQN', 125, 'VR5')
  );
  IF changed_n <> 6 THEN
    RAISE EXCEPTION 'Expected exactly 6 engines updated to their target cylinders value, found %.', changed_n;
  END IF;
END $$;

COMMIT;
